+    }
+    hcclAlgo.assign(buf.data(), strnlen(buf.data(), buf.size()));
+    HCCL_DEBUG("[HcclGetHcclAlgo] hcclAlgo from comm: [%s]", hcclAlgo.c_str());
+
+    return HcclResult::HCCL_SUCCESS;
+}
