12	
13	namespace ops_hccl {
14	
15	InsTempAllReduceNHR::InsTempAllReduceNHR(
16	    const OpParam& param, const u32 rankId, const std::vector<std::vector<u32>>& subCommRanks)
17	    : InsAlgTemplateBase(param, rankId, subCommRanks)
18	{}
19	
20	InsTempAllReduceNHR::~InsTempAllReduceNHR() {}
21	
22	std::vector<CostModelParam> InsTempAllReduceNHR::CalcCostCoeff(CalcCostCoeffParam param)
23	{
24	    AlgNetType netType = AlgNetType::CLOS;
25	    int portNum = (netType == AlgNetType::CLOS) ? 8 : 1;
26	    int taskNum = 10;
27	    float A = 0.0f;
28	    float B = 0.0f;
29	    float C = 0.0f;
30	
31	    CostModelManager::Global()->CalcNHRParams(param.n * 2, netType, portNum, param.rankSize, A);
32	    if (param.needLocalCopy) {
33	        CostModelManager::Global()->CalcLocalCopyParams(param.n * param.rankSize * 2, EngineType::AICPU, B);
34	    } else {
35	        B = 0.0f;
36	    }
37	    CostModelManager::Global()->CalcLatencyParams(taskNum, EngineType::AICPU, C);
38	
39	    std::vector<CostModelParam> params;
40	    params.push_back({A, B, C});
41	    HCCL_DEBUG("[%s] CalcCostCoeff A=%f B=%f C=%f.", __func__, A, B, C);
42	    return params;
43	}
44	
45	u64 InsTempAllReduceNHR::CalcScratchMultiple(BufferType inBuffType, BufferType outBuffType)
46	{
47	    (void)inBuffType;
48	    (void)outBuffType;
49	    u32 multiple = 1;
50	    return multiple;
51	}
52	
53	HcclResult InsTempAllReduceNHR::CalcRes(
54	    HcclComm comm, const OpParam& param, const TopoInfoWithNetLayerDetails* topoInfo,
55	    AlgResourceRequest& resourceRequest)
56	{
57	    std::vector<HcclChannelDesc> level1Channels;
58	    if (topoInfo->level0Topo == Level0Shape::MESH_1D_CLOS && !topoInfo->level0PcieMix) {
59	        std::vector<HcclChannelDesc> myChannelDescs;
60	        CHK_RET(CalcChannelRequestNhrMultiJetty(comm, param, topoInfo, subCommRanks_, myChannelDescs));
61	        for (auto channel : myChannelDescs) {
62	            if (channel.channelProtocol == COMM_PROTOCOL_UBC_CTP) {
63	                level1Channels.push_back(channel);
64	            }
65	        }
66	        HCCL_DEBUG("[InsTempAllReduceNHR::CalcRes] Get Channel Success!");
67	    } else {
68	        CHK_RET(CalcChannelRequestNhr(comm, param, topoInfo, subCommRanks_, level1Channels));
69	    }
70	    resourceRequest.channels.push_back(level1Channels);
71	    channelsPerRank_ = CalcChannelsPerRank(level1Channels);
72	    if (channelsPerRank_ > MAX_JETTY_NUM) {
73	        HCCL_ERROR(
74	            " %s channelsPerRank_ %u is greater than MAX_JETTY_NUM %u", __func__, channelsPerRank_, MAX_JETTY_NUM);
75	    } else {
76	        HCCL_DEBUG(" %s channelsPerRank_ is %u ", __func__, channelsPerRank_);
77	    }
78	    GetRes(resourceRequest);
79	
80	    HCCL_INFO("[InsTempAllReduceNHR] Calculate resource finished.");
81	    return HcclResult::HCCL_SUCCESS;
82	}
83	
84	HcclResult InsTempAllReduceNHR::GetRes(AlgResourceRequest& resourceRequest) const
85	{
86	    u32 threadNum = channelsPerRank_;
87	    resourceRequest.slaveThreadNum = threadNum - 1;
88	    for (u32 index = 0; index < threadNum - 1; index++) {
89	        resourceRequest.notifyNumPerThread.push_back(1);
