142	
143	    CHK_PRT_RET(
144	        subCommRanks_.size() == 0, HCCL_ERROR("[InsTempAllReduceNHR][KernelRun] subCommRanks is empty."),
145	        HcclResult::HCCL_E_INTERNAL);
