148	    CHK_PRT_RET(
149	        rankList_.size() != templateRankSize_,
150	        HCCL_ERROR("[InsTempAllReduceNHR][KernelRun] rank count is invalid in rank list.", myRank_),
151	        HcclResult::HCCL_E_INTERNAL);
152	
153	    // 获取当前rank在rank列表中的序号
154	    CHK_RET(GetAlgRank(myRank_, rankList_, myRankIdx_));
155	
156	    processSize_ = tempAlgParams.sliceSize;
157	    count_ = tempAlgParams.count;
158	    dataType_ = param.DataDes.dataType;
159	    dataTypeSize_ = DATATYPE_SIZE_TABLE[dataType_];
160	    tempAlgParams_ = tempAlgParams;
161	
162	    bool isPcieProtocal = IsPcieProtocol(templateResource.channels); // 判断是否存在pcie链路
163	    isDmaRead_ = isPcieProtocal;                                     // 是否使用Read模式
164	    HCCL_DEBUG("[InsTempAllReduceNHR] Use Dma Read[%d]", isDmaRead_);
165	
166	    if (count_ == 0) {
167	        HCCL_WARNING("[InsTempAllReduceNHR][KernelRun] data count is 0.");
168	        return HcclResult::HCCL_SUCCESS;
169	    }
170	
171	    // 数据切片：向下取整，前N-1个rank各拿sliceSize_，最后rank拿tailSize_
172	    sliceSize_ = (count_ / templateRankSize_) * dataTypeSize_;
173	    tailSize_ = count_ * dataTypeSize_ - sliceSize_ * (templateRankSize_ - 1);
174	
175	    CHK_RET(PrepareDataSplitForMultiChannel(templateResource));
176	    threadNum_ = GetThreadNum();
177	    CHK_PRT_RET(
178	        threadNum_ > templateResource.threads.size(),
179	        HCCL_ERROR(
180	            "[InsTempAllReduceNHR][KernelRun] thread num[%u] more than threads size[%zu].", threadNum_,
181	            templateResource.threads.size()),
182	        HcclResult::HCCL_E_INTERNAL);
183	
184	    // 将数据从input拷贝到hcclBuffer上
185	    CHK_RET(PreCopy(tempAlgParams, templateResource.threads));
186	    if (threadNum_ > 1) {
187	        std::vector<ThreadHandle> subThreads(
188	            templateResource.threads.begin() + 1, templateResource.threads.begin() + threadNum_);
189	        GetNotifyIdxMainToSub(notifyIdxMainToSub_);
190	        CHK_RET(PreSyncInterThreads(templateResource.threads[0], subThreads, notifyIdxMainToSub_));
191	    }
192	    for (u32 channelIdx = 0; channelIdx < channelsPerRank_; channelIdx++) {
193	        // TwoShot算法，第一步ReduceScatter
194	        CHK_RET(RunReduceScatter(tempAlgParams, templateResource.channels, templateResource.threads, channelIdx));
195	        // TwoShot算法，第二步AllGather
196	        CHK_RET(RunAllGather(tempAlgParams, templateResource.channels, templateResource.threads, channelIdx));
197	    }
198	    if (threadNum_ > 1) {
199	        std::vector<ThreadHandle> subThreads(
200	            templateResource.threads.begin() + 1, templateResource.threads.begin() + threadNum_);
201	        GetNotifyIdxSubToMain(notifyIdxSubToMain_);
202	        CHK_RET(PostSyncInterThreads(templateResource.threads[0], subThreads, notifyIdxSubToMain_));
203	    }
204	    // 将数据从hcclBuffer上拷贝到output上
205	    CHK_RET(PostCopy(tempAlgParams, templateResource.threads));
206	
207	    HCCL_INFO("[InsTempAllReduceNHR] KernelRun finished.");
208	
209	    return HcclResult::HCCL_SUCCESS;
210	}
